import sys
import math

def interact(n):
    def query(l, r, left_indices, right_indices):
        print(f"? {l} {r}")
        print(" ".join(map(str, left_indices)))
        print(" ".join(map(str, right_indices)))
        sys.stdout.flush()
        return int(input().strip())

    # Initial queries to gather information
    results = []
    for i in range(1, n):
        force = query(1, 1, [i], [n])
        results.append(force)

    # Identify potential demagnetized magnets
    demagnetized = set()
    for i in range(n-1):
        if results[i] == 0:
            demagnetized.add(i + 1)
            demagnetized.add(n)

    # Further queries to confirm demagnetized magnets
    confirmed_demagnetized = set()
    for i in demagnetized:
        for j in range(1, n + 1):
            if j != i and j not in confirmed_demagnetized:
                force = query(1, 1, [i], [j])
                if force == 0:
                    confirmed_demagnetized.add(j)

    # Output the result
    print(f"! {len(confirmed_demagnetized)} {' '.join(map(str, sorted(confirmed_demagnetized)))}")
    sys.stdout.flush()

t = int(input().strip())
for _ in range(t):
    n = int(input().strip())
    interact(n)
